def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((opp_id, opp))

    # If no opponents alive, bid to cover requirement efficiently
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace (immediate reaction)
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    pressure_bid = None
    if yesterday_bids:
        pressure_bid = max(yesterday_bids)

    # Budget / survival urgency
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate how many no-water days we can tolerate (roughly hp corresponds to days left)
    # If hp is low or we already have consecutive dry days, raise bid.
    urgency = 0
    if hp <= 2:
        urgency += 2
    if hp == 3:
        urgency += 1
    if no_water_days >= 2:
        urgency += 2
    if no_water_days == 1:
        urgency += 1

    # Pressure response: Cindy/Eric averaged very high bids; Alex/David died (overaggressive or underbid).
    # If pressure is extremely high, we bid enough to compete but avoid matching the top bid.
    if pressure_bid is not None:
        if pressure_bid >= DAILY_SALARY * 1.15:
            base = DAILY_SALARY * 0.65
            # urgency bumps
            bid = base + urgency * (DAILY_SALARY * 0.12)
        elif pressure_bid >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * 0.55
            bid = base + urgency * (DAILY_SALARY * 0.10)
        else:
            base = DAILY_SALARY * 0.45
            bid = base + urgency * (DAILY_SALARY * 0.08)
    else:
        # No trace info
        base = DAILY_SALARY * 0.5
        bid = base + urgency * (DAILY_SALARY * 0.08)

    # Supply-aware adjustment: higher supply means cheaper to secure water; lower supply means more competitive.
    # supply is between 15 and 25.
    if supply <= float(MIN_SUPPLY + 1):
        bid *= 1.08
    elif supply >= float(MAX_SUPPLY - 2):
        bid *= 0.95

    # Never bid more than budget
    bid = float(min(budget, bid))

    # Ensure we don't bid zero when we are in danger
    if urgency >= 3 and bid <= 0.0:
        bid = float(min(budget, DAILY_SALARY * 0.9))

    # If budget is tiny, just bid what we can
    if budget <= 1.0:
        return float(budget)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Determine urgency based on health and no_water_days
    urgent = (hp <= 3) or (no_water_days >= 1)
    very_urgent = (hp <= 1) or (no_water_days >= 2)

    if very_urgent:
        # Need water desperately, bid high
        target = DAILY_SALARY * 0.95
    elif urgent:
        # Need water soon, bid moderately high
        target = DAILY_SALARY * 0.7
    else:
        # Not urgent, try to save
        target = DAILY_SALARY * 0.3

    # Adjust based on previous opponent bids
    if prev_bids:
        max_prev = max(prev_bids)
        # If opponents were very aggressive, don't compete unless urgent
        if max_prev >= DAILY_SALARY * 0.85:
            if not urgent:
                target = min(target, DAILY_SALARY * 0.2)
            else:
                # Still may need to outbid slightly
                target = max(target, max_prev + 1.0)
        else:
            # Opponents were moderate, adjust target to be competitive
            if urgent or very_urgent:
                target = max(target, max_prev + 1.0)
            else:
                target = min(target, max_prev * 0.8)

    # Ensure bid is within budget and not negative
    bid = int(min(budget, max(0.0, target)))
    return bid
